def latest_events(events):
    """Select the highest version per document, keeping the first tied event."""
    selected = {}
    for event in events:
        document_id = event["document_id"]
        if (document_id not in selected
                or event["version"] > selected[document_id]["version"]):
            selected[document_id] = event
    return list(selected.values())

