def latest_events(events):
    """Select by highest version, then latest timestamp; keep exact ties first."""
    selected = {}
    for event in events:
        document_id = event["document_id"]
        if (document_id not in selected
                or (event["version"], event["timestamp"])
                > (selected[document_id]["version"], selected[document_id]["timestamp"])):
            selected[document_id] = event
    return list(selected.values())

