import unittest
from copy import deepcopy

from events import latest_events


class EventSelectionTests(unittest.TestCase):
    def test_empty_input(self):
        self.assertEqual(latest_events([]), [])

    def test_multiple_documents(self):
        events = [
            {"document_id": "a", "version": 1, "timestamp": "2026-01-01T00:00:00Z"},
            {"document_id": "b", "version": 2, "timestamp": "2026-01-01T00:00:00Z"},
            {"document_id": "a", "version": 3, "timestamp": "2026-01-02T00:00:00Z"},
        ]
        result = latest_events(events)
        self.assertEqual(len(result), 2)
        selected = {event["document_id"]: event for event in result}
        self.assertEqual(set(selected), {"a", "b"})
        self.assertIs(selected["a"], events[2])
        self.assertIs(selected["b"], events[1])

    def test_unsorted_versions(self):
        events = [
            {"document_id": "a", "version": version, "timestamp": "2026-01-01T00:00:00Z"}
            for version in (3, 1, 5, 2, 4)
        ]
        selected = latest_events(events)
        self.assertEqual(len(selected), 1)
        self.assertIs(selected[0], events[2])

    def test_equal_versions_choose_latest_timestamp(self):
        events = [
            {"document_id": "a", "version": 2, "timestamp": timestamp}
            for timestamp in ("2026-01-01T00:00:00Z", "2027-01-01T00:00:00Z", "2025-01-01T00:00:00Z")
        ]
        for ordered in (events, list(reversed(events))):
            with self.subTest(ordered=ordered):
                self.assertIs(latest_events(ordered)[0], events[1])

    def test_equal_versions_and_timestamps_preserve_first_occurrence(self):
        events = [
            {"document_id": "a", "version": 2, "timestamp": "2026-01-01T00:00:00Z"}
            for _ in range(2)
        ]
        self.assertIs(latest_events(events)[0], events[0])

    def test_version_outranks_timestamp(self):
        events = [
            {"document_id": "a", "version": 3, "timestamp": "2025-01-01T00:00:00Z"},
            {"document_id": "a", "version": 2, "timestamp": "2027-01-01T00:00:00Z"},
        ]
        for ordered in (events, list(reversed(events))):
            with self.subTest(ordered=ordered):
                self.assertIs(latest_events(ordered)[0], events[0])

    def test_inputs_are_not_mutated(self):
        events = [
            {"document_id": "a", "version": 2, "timestamp": "2026-01-01T00:00:00Z"},
            {"document_id": "a", "version": 2, "timestamp": "2026-01-03T00:00:00Z"},
            {"document_id": "a", "version": 1, "timestamp": "2026-01-02T00:00:00Z"},
        ]
        original_values = deepcopy(events)
        original_objects = list(events)
        selected = latest_events(events)
        self.assertEqual(events, original_values)
        for event, original in zip(events, original_objects):
            self.assertIs(event, original)
        self.assertIsNot(selected, events)
        self.assertIs(selected[0], events[1])
